package app.remotehub

import app.remotehub.data.createSecretBox
import com.goterl.lazysodium.LazySodiumJava
import com.goterl.lazysodium.SodiumJava
import com.goterl.lazysodium.utils.Key
import com.goterl.lazysodium.utils.KeyPair
import java.util.Base64
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotEquals
import kotlin.test.assertTrue

/**
 * Verifies that the sealed-box implementation shipped in the app produces values
 * that GitHub can open with the repository private key. The recipient key pair is
 * generated by libsodium itself, so the test exercises the real crypto path.
 */
class SecretBoxTest {
    private val sodium = LazySodiumJava(SodiumJava())

    private fun KeyPair.publicBase64(): String =
        Base64.getEncoder().encodeToString(publicKey.asBytes)

    private fun KeyPair.secretBase64(): String =
        Base64.getEncoder().encodeToString(secretKey.asBytes)

    @Test
    fun sealedValueOpensWithRecipientSecretKey() {
        val pair = sodium.cryptoBoxKeypair()
        val box = createSecretBox()
        val message = "tskey-auth-kExampleSecretValue123"
        val sealed = box.seal(message, pair.publicBase64())
        val opened = sodium.cryptoBoxSealOpenEasy(sealed, pair.secretBase64())
        assertEquals(message, opened)
    }

    @Test
    fun sealedValueIsBase64AndNonDeterministic() {
        val pair = sodium.cryptoBoxKeypair()
        val box = createSecretBox()
        val a = box.seal("same", pair.publicBase64())
        val b = box.seal("same", pair.publicBase64())
        assertNotEquals(a, b)
        assertTrue(a.none { it == '\n' || it == ' ' })
        // A sealed box is 48 bytes of overhead plus the message, base64 encoded.
        assertTrue(Base64.getDecoder().decode(a).size >= 48 + "same".length)
    }

    @Test
    fun unicodeSecretRoundTrips() {
        val pair = sodium.cryptoBoxKeypair()
        val box = createSecretBox()
        val message = "گذرواژهٔ فارسی با نویسه‌های خاص !@#"
        val sealed = box.seal(message, pair.publicBase64())
        assertEquals(message, sodium.cryptoBoxSealOpenEasy(sealed, pair.secretBase64()))
    }

    @Test
    fun wrongRecipientCannotOpen() {
        val pair = sodium.cryptoBoxKeypair()
        val other = sodium.cryptoBoxKeypair()
        val sealed = createSecretBox().seal("secret", pair.publicBase64())
        val opened = runCatching { sodium.cryptoBoxSealOpenEasy(sealed, other.secretBase64()) }
        assertTrue(opened.isFailure || opened.getOrNull().isNullOrEmpty())
    }

    @Test
    fun repositoryKeyShapeIsAccepted() {
        val publicKey = sodium.cryptoBoxKeypair().publicKey
        assertEquals(32, publicKey.asBytes.size)
        val base64 = Base64.getEncoder().encodeToString(publicKey.asBytes)
        assertEquals(44, base64.length)
        val sealed = createSecretBox().seal("value", base64)
        assertTrue(sealed.length > 44)
    }

    @Test
    fun longSecretRoundTrips() {
        val pair = sodium.cryptoBoxKeypair()
        val message = "x".repeat(4096)
        val sealed = createSecretBox().seal(message, pair.publicBase64())
        assertEquals(message, sodium.cryptoBoxSealOpenEasy(sealed, pair.secretBase64()))
    }
}
